                                                    <div className={cn(
                                                        "text-[10px] font-black uppercase tracking-widest",
                                                        cicpaDays !== null && cicpaDays < 0 ? "text-rose-500" :
                                                        cicpaDays !== null && cicpaDays < 15 ? "text-orange-500" :
                                                        "text-emerald-500"
                                                    )}>
                                                        {cicpaDays !== null ? (cicpaDays < 0 ? 'Expired' : `${cicpaDays} Days Left`) : '-'}
                                                    </div>
